"""Render self-contained observability helpers from named provider data."""

from __future__ import annotations

import base64
import gzip

from hooks.manifest import GeneratedTarget
from hooks.providers import Provider


SHEBANG = "#!/usr/bin/env python3\n"
HEADER = "# Generated from hooks/families/observability.py by scripts/generate-hooks.py. Do not edit.\n"

# This is the canonical Copilot implementation compressed solely to keep the
# renderer readable. Rendered provider files remain ordinary, self-contained
# Python and are the reviewed runtime representation.
_COPILOT_SOURCE_GZIP_BASE64 = ""


def _canonical_body() -> str:
    return gzip.decompress(base64.b64decode(_COPILOT_SOURCE_GZIP_BASE64)).decode("utf-8")


def _provider_replacements(provider: Provider) -> tuple[tuple[str, str], ...]:
    runtime = provider.name
    prefix = provider.observability_environment_prefix
    home = provider.runtime_home_name
    return (
        ('OBSERVABILITY_RUNTIME = "copilot"', f'OBSERVABILITY_RUNTIME = "{runtime}"'),
        ('_truthy_env("COPILOT_OBSERVABILITY_DISABLE", "OBSERVABILITY_DISABLE")',
         f'_truthy_env("{prefix}_OBSERVABILITY_DISABLE", "OBSERVABILITY_DISABLE")'),
        ('_truthy_env("OBSERVABILITY_CAPTURE_EVENT", "COPILOT_OBSERVABILITY_CAPTURE_EVENT")',
         f'_truthy_env("OBSERVABILITY_CAPTURE_EVENT", "{prefix}_OBSERVABILITY_CAPTURE_EVENT")'),
        ('_truthy_env("OBSERVABILITY_INCLUDE_TRANSCRIPT", "COPILOT_OBSERVABILITY_INCLUDE_TRANSCRIPT")',
         f'_truthy_env("OBSERVABILITY_INCLUDE_TRANSCRIPT", "{prefix}_OBSERVABILITY_INCLUDE_TRANSCRIPT")'),
        ('os.environ.get("COPILOT_OBSERVABILITY_LOG_PATH")',
         f'os.environ.get("{prefix}_OBSERVABILITY_LOG_PATH")'),
        ('Path.home() / ".copilot" / "hooks" / "logs"',
         f'Path.home() / "{home}" / "hooks" / "logs"'),
        ('os.environ.get("COPILOT_OBSERVABILITY_LOCK_WAIT_MS")',
         f'os.environ.get("{prefix}_OBSERVABILITY_LOCK_WAIT_MS")'),
        ('os.environ.get("COPILOT_OBSERVABILITY_SOURCE_EVENT_NAME")',
         f'os.environ.get("{prefix}_OBSERVABILITY_SOURCE_EVENT_NAME")'),
    )


def render(provider: Provider, target: GeneratedTarget) -> str:
    """Render a complete provider-local helper without runtime templating."""
    if target.provider != provider.name or provider.name not in {"copilot", "gemini"}:
        raise ValueError(f"Unsupported observability target/provider: {target.output_path}")
    body = _canonical_body()
    if provider.name == "gemini":
        for copilot_value, provider_value in _provider_replacements(provider):
            if body.count(copilot_value) != 1:
                raise ValueError(f"Expected one observability adapter site: {copilot_value}")
            body = body.replace(copilot_value, provider_value)
    return SHEBANG + HEADER + body
